-- Cogni v0.14 — curated audience-native lesson families.
-- Five distinctive short lessons per audience. Existing lessons remain valid fallback content.

create temporary table tmp_v014_lesson(
 content_key text,audience text,slug text,title text,subtitle text,emoji text,skill_slug text,difficulty int,
 scenario text,category text,function_tags text[],goal_tags text[],complexity smallint,content jsonb
) on commit drop;

insert into tmp_v014_lesson values
('v014_lesson_uni_claim_chain','university_student','uni-claim-chain','The claim ladder','Do not let a source travel further than its evidence','🪜','source-quality',44,'University • Assessed work','essay and sources',array['study_research'],array['academic_performance'],2,jsonb_build_object('story','You read a confident sentence in an AI draft. It cites a news story, which cites a company report, which cites a survey the company commissioned.','twist','Four links do not make four independent sources. They can all be one piece of evidence wearing different clothes.','principle','Trace an important claim back until you reach the evidence that actually produced it.','try_it','Where in that chain would you look first to decide whether the claim belongs in your assignment?','reveal','The original survey: who was asked, how, what was measured and who paid for it.','ai_age','AI often compresses a long source chain into one fluent sentence. Your job is to reopen the chain before you rely on it.')),
('v014_lesson_uni_ai_boundary','university_student','uni-ai-boundary','When AI stops being “just editing”','Notice when the task changes','✦','ai-trust-boundaries',45,'University • AI-assisted study','AI study',array['study_research'],array['work_effectively_with_ai'],2,jsonb_build_object('story','You ask AI to tidy a paragraph. It adds a new statistic, a quotation and a source. The prose is better—but the task has quietly changed.','twist','Editing became content generation. That creates new verification and academic-integrity responsibilities.','principle','The right level of checking depends on what the AI actually did, not what you originally asked it to do.','try_it','Which additions would you independently verify before using the paragraph?','reveal','Every new factual claim and source, plus whether that type of AI assistance fits your course rules.','ai_age','Use AI boldly for learning, but notice when it crosses from helping your thinking into supplying evidence or work you must personally stand behind.')),
('v014_lesson_uni_social','university_student','uni-viral-evidence','The claim that has 2 million views','Popularity is not evidence quality','📱','evidence-evaluation',44,'University • Social media claim','misinformation',array['study_research'],array['make_better_decisions','critical_thinking_general'],2,jsonb_build_object('story','A video about sleep gets two million views and thousands of comments saying “this worked for me”. You are tempted to treat the crowd as evidence.','twist','A large audience can make a claim visible without making the sample controlled, representative or independent.','principle','Judge evidence by how it was produced and whether it tests the claim—not by how many people saw or repeated it.','try_it','What would you want to know before changing your sleep routine because of the video?','reveal','Who was studied, compared with what, over what period, with what outcome measure—and whether the creator benefits from the claim.','ai_age','AI may repeat popular claims because they appear often. Frequency in training data is not the same as quality of evidence.')),
('v014_lesson_uni_group','university_student','uni-group-consensus','When the group agrees too quickly','Agreement can hide missing challenge','👥','bias-recognition',45,'University • Group project','group work',array['study_research'],array['academic_performance','critical_thinking_general'],2,jsonb_build_object('story','Your project group quickly agrees on an explanation because the most confident member proposes it first. Nobody wants to slow the meeting down.','twist','Fast agreement can be coordination—or anchoring. You cannot tell which without giving alternatives a fair chance.','principle','Before locking in a group conclusion, ask for one credible alternative and one fact that would change the group’s mind.','try_it','How could you challenge the idea without making the conversation adversarial?','reveal','Ask something specific and shared: “What else could explain this, and what evidence would separate the two explanations?”','ai_age','AI can strengthen the first framing supplied by a group. Use it to generate alternatives, not just to elaborate the current favourite.')),
('v014_lesson_uni_career','university_student','uni-career-signal','Prestige versus learning','A shiny signal can hide the real trade-off','🚀','decision-uncertainty',47,'University • Graduate choice','career decision',array['study_research'],array['graduate_readiness','make_better_decisions'],2,jsonb_build_object('story','One graduate role has a famous name and narrow work. Another is less prestigious but offers a manager who coaches, broader responsibility and faster learning.','twist','Prestige is easy to compare because it is visible. The qualities that shape your development are harder to measure.','principle','Build the decision around the outcomes you care about, then compare the options using evidence about the actual experience.','try_it','Which two facts would most change your choice between the roles?','reveal','Usually the work you will actually do, who you will learn from, progression evidence, constraints and future options—not the logo alone.','ai_age','AI can compare employer brands instantly. Your judgement is needed to decide which criteria actually matter for your next stage.')),

('v014_lesson_grad_question','graduate_early_career','grad-one-question','The question that makes you look senior','Clarity beats pretending to know','🎯','better-questions',49,'Graduate • Ambiguous request','workplace judgement',array['general_professional'],array['progress_faster','communicate_with_confidence'],2,jsonb_build_object('story','A senior colleague asks for “some analysis” by lunch. A new graduate spends two hours building charts. At 11:45 they learn the meeting only needs one number: whether to renew a contract.','twist','The work was competent. The judgement about what the work was for was missing.','principle','Before doing ambiguous work, ask the smallest question that reveals the decision, output and constraint.','try_it','What single question would you ask before opening the spreadsheet?','reveal','Something like: “What decision does this need to support, and what would change that decision?”','ai_age','AI makes it easier than ever to produce a lot of work quickly. The advantage shifts toward people who ask the right question before generating it.')),
('v014_lesson_grad_uncertainty','graduate_early_career','grad-say-not-sure','How to say “I’m not sure” professionally','Uncertainty can increase credibility','🗣️','decision-uncertainty',50,'Graduate • Senior meeting','communication',array['general_professional'],array['communicate_with_confidence'],2,jsonb_build_object('story','You are asked in a meeting why a metric fell. You have one plausible explanation but have not tested it.','twist','A confident guess may feel safer in the moment, but it creates more credibility risk than a precise statement of what you know.','principle','Separate fact, hypothesis and next check.','try_it','How would you answer in one sentence without sounding evasive?','reveal','“The drop is real. My leading hypothesis is X, but I have not separated it from Y yet; I can confirm that after the meeting.”','ai_age','AI can always produce a confident explanation. Your professional value includes knowing when the evidence has not earned one yet.')),
('v014_lesson_grad_feedback','graduate_early_career','grad-feedback-signal','The feedback that stings','Separate the signal from the emotion','🪞','critical-thinking',50,'Graduate • Feedback conversation','feedback',array['general_professional'],array['progress_faster','build_professional_judgement'],2,jsonb_build_object('story','A manager says your update was “too detailed and not decision-focused”. Your first reaction is that they did not understand the complexity.','twist','The feedback may be incomplete or poorly phrased, but defensiveness can make you discard useful signal with the noise.','principle','Ask what observable behaviour the feedback refers to, what outcome it affected and what a better version would look like.','try_it','What question turns vague criticism into something you can test next time?','reveal','For example: “Which part made the decision less clear, and what would you have wanted on the first page instead?”','ai_age','AI can help rewrite work, but professional growth still depends on diagnosing what the human audience actually needed.')),
('v014_lesson_grad_load','graduate_early_career','grad-urgent-important','Urgent is not a priority system','Ask about consequence, not volume','⏱️','missing-information',49,'Graduate • Workload','prioritisation',array['general_professional'],array['progress_faster','build_professional_judgement'],2,jsonb_build_object('story','Three stakeholders mark work “urgent”. You have four hours and six hours of tasks. Doing everything is impossible.','twist','The missing information is not which person is most senior. It is what happens if each item moves, what is fixed, and what can be reduced.','principle','When demand exceeds capacity, surface consequence, true deadlines, effort and flexibility before choosing the order.','try_it','What would you ask the three requesters before promising all three deadlines?','reveal','Ask what decision or event depends on the work, the real latest useful time, minimum viable scope and whether timing can move.','ai_age','AI can accelerate tasks, but it can also make unrealistic workload promises look feasible. Capacity judgement still matters.')),
('v014_lesson_grad_ai_client','graduate_early_career','grad-ai-commitment','The sentence that became a commitment','Good writing is not approval','✉️','ai-trust-boundaries',49,'Graduate • Client communication','AI-assisted communication',array['sales_client','general_professional'],array['work_effectively_with_ai','communicate_with_confidence'],2,jsonb_build_object('story','AI drafts a polished client response: “We will resolve this by Friday.” The team has only said Friday is possible.','twist','The AI improved the sentence and quietly changed the organisation’s commitment.','principle','Before sending AI-assisted external communication, check claims, promises and decisions that require an accountable person to own them.','try_it','Which words in a draft should make you stop and verify before sending?','reveal','Dates, guarantees, prices, legal positions, factual claims and anything that creates a commitment or expectation.','ai_age','The professional advantage is not merely faster drafting; it is knowing which parts of the draft cannot be delegated to fluency.')),

('v014_lesson_junior_recommendation','junior_professional','junior-recommendation','From analysis to a recommendation people trust','Show what carries the conclusion','🧭','assumption-identification',57,'Junior professional • Recommendation','recommendation quality',array['general_professional'],array['make_recommendations','build_professional_judgement'],3,jsonb_build_object('story','Two analysts reach the same recommendation. One presents twenty slides of analysis. The other says: “I recommend B. It wins if these two assumptions hold; this one is the biggest risk; here is what would change my view.”','twist','The second analyst may have done less visible work, but makes the decision logic easier to challenge and trust.','principle','A strong recommendation exposes the assumptions carrying it and the evidence that could change it.','try_it','What is the one assumption in your current work that would most change the recommendation if it were wrong?','reveal','That is usually the assumption worth testing or surfacing first—not the easiest assumption to quantify.','ai_age','AI can generate analysis cheaply. Trusted professionals make the decision logic auditable.')),
('v014_lesson_junior_crossfunctional','junior_professional','junior-crossfunctional','Same skill, different function','Evidence changes shape; judgement does not','🔀','evidence-evaluation',56,'Junior professional • Cross-functional work','functional variety',array['general_professional'],array['build_professional_judgement'],3,jsonb_build_object('story','A marketer sees an A/B test, an engineer sees incident logs, HR sees interview evidence and finance sees a forecast. Each can still make the same mistake: treating the easiest available measure as the answer.','twist','The domain changes. The judgement test—does this evidence support this claim?—does not.','principle','Judge evidence against the decision it must support, not against whether it looks quantitative or professional.','try_it','What evidence in your own function is often treated as stronger than it really is?','reveal','The useful answer is the proxy, metric or source people routinely over-trust in your work.','ai_age','AI is good at translating weak evidence into polished language across every function. The transferable skill is testing the evidence-to-claim link.')),
('v014_lesson_junior_rootcause','junior_professional','junior-root-cause','The first plausible cause','Timing is not proof','🧰','correlation-causation',57,'Junior professional • Incident analysis','root-cause analysis',array['technology_engineering','operations'],array['analyse_information','build_professional_judgement'],3,jsonb_build_object('story','A system fails ten minutes after a release. Everyone immediately calls the release the root cause. Logs also show capacity pressure building for hours beforehand.','twist','The release is a good hypothesis because of timing. Calling it the cause before testing alternatives can produce the wrong fix.','principle','Use chronology to generate hypotheses, then test each explanation against evidence that could distinguish it.','try_it','What evidence would separate “the release caused it” from “capacity caused it”?','reveal','Compare failure signatures, pre-release behaviour, component logs, rollback response and whether the issue reproduces independently of the release.','ai_age','AI can propose root causes rapidly. Treat the list as hypotheses and ask what evidence would make each one fail.')),
('v014_lesson_junior_influence','junior_professional','junior-challenge-up','Challenge upwards without performing confidence','Make the risk easy to inspect','🗣️','better-questions',58,'Junior professional • Senior stakeholder','managing upwards',array['general_professional'],array['manage_upwards','communicate_with_confidence'],3,jsonb_build_object('story','A senior sponsor strongly prefers Option A. Your analysis suggests its headline benefit depends on one weak assumption.','twist','You do not need to “win” against the sponsor. You need to make the decision-critical assumption visible enough to inspect.','principle','Challenge the evidence or assumption specifically, and connect it to what would change the decision.','try_it','How would you raise the issue in one sentence?','reveal','For example: “Option A still leads if X holds; can we test X before commitment because if it is wrong the ranking reverses?”','ai_age','AI can give you perfect wording, but trusted judgement comes from identifying the point worth challenging in the first place.')),
('v014_lesson_junior_range','junior_professional','junior-range','A recommendation without false precision','Show what changes the answer','📊','decision-uncertainty',58,'Junior professional • Forecast','recommendation under uncertainty',array['finance_commercial','general_professional'],array['make_recommendations','communicate_with_confidence'],3,jsonb_build_object('story','You are asked for one forecast number even though two unresolved assumptions could move the result materially.','twist','A single number may be convenient for a slide while making the decision less honest.','principle','Give a recommendation, but show the assumptions and range that can change it rather than hiding uncertainty in a precise point estimate.','try_it','Which assumption deserves to sit next to the headline number?','reveal','The one whose plausible movement can reverse the decision or materially change the downside—not every minor variable.','ai_age','AI can produce exact forecasts on demand. Strong professionals know which uncertainty deserves to remain visible.')),

('v014_lesson_mgr_system','management','manager-system-effects','The team does what the system rewards','Manage the system, not just the person','🧩','problem-framing',64,'Management • Team incentives','management system',array['people_hr','operations'],array['people_decisions','organisational_performance'],4,jsonb_build_object('story','A manager tells a team to focus on quality while bonuses reward speed. Quality falls. The manager responds with more reminders about quality.','twist','The behaviour may be rational inside the system the manager created.','principle','Before treating a behaviour problem as a people problem, inspect incentives, capacity, measures and decision rights.','try_it','What does your team’s current system reward in practice, regardless of what leaders say they value?','reveal','Look at what gets measured, praised, promoted, escalated and punished. Those signals usually beat slogans.','ai_age','AI productivity metrics can intensify the same problem: if the measure rewards output volume, people and tools will optimise output volume.')),
('v014_lesson_mgr_tradeoff','management','manager-tradeoffs','A manager’s hardest word','“No” is sometimes the capacity decision','⚖️','decision-uncertainty',65,'Management • Prioritisation','competing priorities',array['operations','strategy'],array['prioritisation','resource_allocation'],4,jsonb_build_object('story','A team has capacity for two priorities. Leadership sponsors three. Every initiative has a credible business case, so the manager calls all three “top priority”.','twist','The conflict did not disappear. It moved into overtime, delays and local trade-offs made by people with less context.','principle','When objectives conflict, make the trade-off explicit rather than hiding it inside an impossible plan.','try_it','Which current priority would you stop or delay if adding one more item became unavoidable?','reveal','If that question is impossible to answer, the priority list is probably not yet a real priority list.','ai_age','AI can make every initiative look more efficient. It does not remove finite attention, coordination or organisational capacity.')),
('v014_lesson_mgr_accounts','management','manager-two-stories','Two people, two believable stories','Reconstruct before you judge','👥','evidence-evaluation',64,'Management • Performance','conflicting accounts',array['people_hr'],array['people_decisions','managing_risk'],4,jsonb_build_object('story','An employee says priorities changed repeatedly. Their project lead says the employee did not raise risk soon enough. Both accounts sound credible.','twist','A manager can be pushed into choosing which person seems more convincing instead of reconstructing the sequence.','principle','Separate observations, expectations, changes and communication before deciding what the outcome says about performance.','try_it','What evidence would you ask for before giving feedback or a rating?','reveal','Agreed priorities, dated changes, escalation points, responses, dependencies and what each person reasonably knew at the time.','ai_age','AI summaries can flatten conflicting accounts into one neat narrative. Keep the underlying evidence visible for consequential people decisions.')),
('v014_lesson_mgr_kpi2','management','manager-kpi-game','The target becomes the job','Metrics change behaviour','🎛️','problem-framing',66,'Management • KPI design','incentives and gaming',array['people_hr','operations'],array['organisational_performance','people_decisions'],5,jsonb_build_object('story','A service team is rewarded for closing tickets quickly. Closure volume rises. Reopened tickets and complaints rise too.','twist','The team may be responding rationally to the measurement system rather than suddenly caring less about customers.','principle','When a metric becomes a target, inspect the behaviours it encourages and the outcomes it omits.','try_it','What balancing measure would reveal whether speed is damaging the actual service outcome?','reveal','Reopen rates, repeat contacts, resolution quality or customer outcomes can expose whether “closed” means “solved”.','ai_age','AI can optimise measured work dramatically. Managers must make sure the measured target still represents the real objective when optimisation gets easier.')),
('v014_lesson_mgr_delegate','management','manager-decision-rights','Delegation is not “just handle it”','Define ownership and escalation','🧭','decision-uncertainty',64,'Management • Delegation','decision rights',array['people_hr','operations'],array['people_decisions','prioritisation'],4,jsonb_build_object('story','A capable team member keeps asking you to approve routine decisions. You tell them to “take more ownership”. The questions keep coming.','twist','The person may not lack confidence. The decision boundary may be unclear: what can they decide, what needs consultation and what must be escalated?','principle','Good delegation gives ownership plus clear constraints, escalation triggers and feedback loops.','try_it','What is one decision your team currently escalates that could have a clearer boundary?','reveal','Define the decision, the limit, the information needed, what “good” looks like and the trigger that brings it back to you.','ai_age','AI can increase the number of decisions a team can generate. Clear decision rights become more—not less—important.')),

('v014_lesson_exec_optionality','executive','exec-optionality','Commitment is a design choice','You can buy information without buying the whole future','♟','decision-uncertainty',71,'Executive • Strategic investment','optionality',array['strategy','finance_commercial'],array['capital_allocation','strategy'],5,jsonb_build_object('story','A strategic opportunity has large upside and wide uncertainty. The debate becomes binary: “Do we believe in it or not?”','twist','The binary framing ignores a third variable: how much to commit before learning more.','principle','Under uncertainty, choose not only the direction but the size, timing and reversibility of commitment.','try_it','What is the smallest investment that would materially reduce uncertainty without destroying the option to scale?','reveal','That staged commitment can have value even if its near-term return is lower, because it purchases information and preserves optionality.','ai_age','AI can generate sharper forecasts; it cannot eliminate structural uncertainty. Strategic advantage often comes from designing decisions that learn.')),
('v014_lesson_exec_incentives','executive','exec-incentives','The metric enters the system','Every measure becomes an intervention','🕸️','bias-recognition',72,'Executive • Incentive design','system effects',array['strategy','people_hr'],array['organisational_performance','governance_risk'],6,jsonb_build_object('story','A board wants more growth, so it increases the weight of revenue in executive incentives. Revenue rises—and so do discounts, low-quality deals and deferred maintenance.','twist','The metric did not simply measure performance. Once linked to reward, it changed the organisation’s behaviour.','principle','Evaluate important measures by the behaviour they will rationally create at the edges, not only by what they intend to encourage.','try_it','Which current enterprise metric would you expect smart people to game if the reward for hitting it doubled?','reveal','The answer reveals where governance should include balancing measures, guardrails or judgement rather than a single target.','ai_age','AI makes optimisation easier. That raises the importance of choosing objectives and constraints that remain sensible when optimised aggressively.')),
('v014_lesson_exec_crisis2','executive','exec-crisis-sequence','When every option has a cost','Sequence irreversible decisions first','🚨','decision-uncertainty',73,'Executive • Crisis','crisis decision',array['strategy','legal_compliance'],array['governance_risk','organisational_performance'],6,jsonb_build_object('story','A serious allegation spreads rapidly. Facts are incomplete. Silence carries reputational cost; a definitive statement could be wrong; an operational hazard may still be live.','twist','The decision is not simply “speak or wait”. Different actions have different reversibility and harm profiles.','principle','In a crisis, sequence actions around immediate harm, verified facts, decision ownership and commitments that are difficult to unwind.','try_it','What would you insist is known or owned in the first hour?','reveal','Who owns the decision, whether any ongoing harm must be contained, which facts are verified, what is unknown, and when stakeholders will next be updated.','ai_age','AI can accelerate synthesis and drafting during a crisis. It cannot own the truthfulness or consequences of the statement.')),
('v014_lesson_exec_portfolio','executive','exec-portfolio-view','A good project can still be the wrong investment','Capital decisions live in a portfolio','♜','decision-uncertainty',74,'Executive • Capital allocation','portfolio strategy',array['strategy','finance_commercial'],array['capital_allocation','strategy'],6,jsonb_build_object('story','Three projects all clear their individual return hurdles. Funding all three would increase concentration, weaken the balance sheet and consume the same scarce leadership team.','twist','Project-by-project approval can produce a portfolio nobody would choose deliberately.','principle','Judge capital allocation using risk-adjusted value, strategic fit, concentration, optionality and what each commitment prevents elsewhere.','try_it','Which constraint makes the three projects different when viewed as a portfolio rather than standalone cases?','reveal','Shared risks, scarce capabilities, financing headroom, leadership attention and the option value of preserving capacity for future choices.','ai_age','AI can improve every individual business case. Executive judgement still decides whether the combined portfolio is coherent.')),
('v014_lesson_exec_sources','executive','exec-source-independence','Five sources, one assumption','Count independent evidence, not citations','🔗','source-quality',71,'Executive • Board evidence','strategic evidence',array['strategy'],array['governance_risk','strategy'],5,jsonb_build_object('story','A board paper cites five reports supporting the same market-size estimate. Digging deeper shows four of them ultimately reference the fifth.','twist','The citation count created the appearance of convergence without independent evidence.','principle','Trace strategic evidence far enough to see whether sources are independent, how the estimate was produced and what assumptions carry it.','try_it','What would you ask the team to show on the board page instead of five logos?','reveal','The underlying source, method, range, key assumptions, independent corroboration and what part of the decision depends on the estimate.','ai_age','AI can aggregate citations faster than humans. That makes source lineage and genuine independence more important, not less.'));

insert into public.daily_lessons(id,content_key,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order,audience_segments,difficulty,scenario_context,scenario_category,function_tags,goal_tags,complexity_level)
select gen_random_uuid(),s.content_key,s.slug,s.title,s.subtitle,s.emoji,sk.id,s.content,3,true,3000+row_number() over(order by audience,content_key),array[s.audience],s.difficulty,s.scenario,s.category,s.function_tags,s.goal_tags,s.complexity
from tmp_v014_lesson s join public.skills sk on sk.slug=s.skill_slug
where not exists(select 1 from public.daily_lessons l where l.content_key=s.content_key);
